/// The embedded details are the retained bytes, and every subset decodes
/// through the production models.
@MainActor
final class FootballRetainedAdapter10868Tests: XCTestCase {
    private typealias F = FootballRetained10868

    func testTheEmbeddedDetailsAreTheRetainedBytes() {
        XCTAssertEqual(F.sha256(F.pregameDetail), "1f81fa527d56660a7c3fb0b495b0a8489aa7b202a9cc200558c3b817940b0eb9")
        XCTAssertEqual(F.sha256(F.liveDetail), "031d81508103f23bdef9383ac2e8f3d0711e57bd6d3adc40d22fee7763d778ae")
        XCTAssertEqual(F.sha256(F.finalDetail), "b22f37929e4d723b3c2800e754b8874327bff12b2b26739b6a8cccf5b1f9f7ef")
        XCTAssertEqual(F.sha256(F.packersDetail), "fff375092493057ddb6339c6d961342a33856db79c85861a4ff10e5e17cf95a0")
    }

    func testEverySubsetDecodesThroughTheProductionModels() throws {
        let pregame = try F.detail(F.pregameDetail)
        XCTAssertEqual(pregame.id, 14780558)
        XCTAssertEqual(pregame.status, "scheduled")
        XCTAssertEqual(pregame.sport, "americanfootball_nfl")
        let live = try F.detail(F.liveDetail)
        XCTAssertEqual(live.id, 14639175)
        XCTAssertEqual(live.status, "live")
        XCTAssertEqual(live.awayScore, 14)
        XCTAssertEqual(live.homeScore, 7)
        let final = try F.detail(F.finalDetail)
        XCTAssertTrue(EventState.isFinished(final.status))
        XCTAssertEqual(final.homeScore, 19)
        XCTAssertEqual(final.awayScore, 17)
        let packers = try F.detail(F.packersDetail)
        XCTAssertEqual(packers.id, 14780562)
        XCTAssertEqual(packers.homeScore, 23)

        let liveHistory = try F.history(F.liveHistory)
        XCTAssertEqual(liveHistory.bookmakerHistory?["draftkings"]?.count, 3)
        XCTAssertEqual(liveHistory.scoreHistory?.count, 6)
        XCTAssertEqual(liveHistory.periodMarkers?.count, 4)
        XCTAssertEqual(liveHistory.aggregateLine?.count, 7)
        let packersHistory = try F.history(F.packersHistory)
        XCTAssertEqual(packersHistory.bookmakerHistory?["ballybet"]?.count, 12)
        XCTAssertEqual(packersHistory.scoreHistory?.count, 9)

        XCTAssertEqual(try F.markets(F.pregameMarkets).playerProps?.count, 26)
        XCTAssertEqual(try F.markets(F.liveMarkets).playerProps?.count, 18)
        XCTAssertEqual(try F.markets(F.finalMarkets).playerProps?.count, 27)
        // The twelve quarter-winner originals and the four matrix questions on them.
        XCTAssertEqual(try F.markets(F.finalMarkets).periodMarkets?.count, 12)
        XCTAssertEqual(try F.markets(F.finalMarkets).gameQuestionMatrix?.questions.count, 4)
        XCTAssertEqual(F.quarterBinding.originals.count, 12)
    }
}
